mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER ( ORDER BY CASE WHEN P.TOP_FIX_YN = 'Y' THEN 0 ELSE 1 END, P.REG_DTTM DESC, TO_NUMBER(REGEXP_REPLACE(P.ANN_NO, '[^0-9]', '')) DESC ) AS ROW_NO , P.ANN_NO , P.BOARD_NO , B.APT_CMPLEX_NO , P.TTL , P.CN , P.WRTR_ID , P.REG_DTTM , P.MDF_DTTM , NVL(P.INQ_CNT, 0) AS INQ_CNT , P.DEL_YN , P.ATCH_FILE_ID , P.TOP_FIX_YN , CASE WHEN P.ATCH_FILE_ID IS NOT NULL THEN 1 ELSE 0 END AS FILE_CNT FROM APT_ANN_BOARD_POST P INNER JOIN APT_BOARD_INSTANCE B ON P.BOARD_NO = B.BOARD_NO WHERE P.DEL_YN = 'N' AND B.USE_YN = 'Y' AND B.BOARD_TY_CD = 'NOTICE' AND B.APT_CMPLEX_NO = #{aptCmplexNo} AND P.BOARD_NO = #{boardNo}
AND P.ANN_NO LIKE '%' || #{searchAnnNo} || '%'
AND P.TTL LIKE '%' || #{searchTtl} || '%'
AND P.WRTR_ID LIKE '%' || #{searchWrtrId} || '%'
AND TRUNC(P.REG_DTTM) >= TO_DATE(#{searchStartDt}, 'YYYY-MM-DD')
AND TRUNC(P.REG_DTTM) <= TO_DATE(#{searchEndDt}, 'YYYY-MM-DD')
) WHERE ROW_NO BETWEEN #{startRow} AND #{endRow}

mapper.insert:
INSERT INTO APT_ANN_BOARD_POST
(
  ANN_NO
, BOARD_NO
, TTL
, CN
, WRTR_ID
, TOP_FIX_YN
, REG_DTTM
, INQ_CNT
, DEL_YN
, ATCH_FILE_ID
)
VALUES
    (
      'NTC' || TO_CHAR(SYSDATE, 'YYMMDD') || LPAD(SEQ_ANN_BOARD_POST.NEXTVAL, 4, '0')
    , #{boardNo}
    , #{ttl}
    , #{cn}
    , #{wrtrId}
    , #{topFixYn}
    , SYSDATE
    , 0
    , 'N'
    , #{atchFileId}
    )

mapper.update:
UPDATE APT_ANN_BOARD_POST
SET TTL = #{ttl}
  , CN = #{cn}
  , TOP_FIX_YN = #{topFixYn}
  , MDF_DTTM = SYSDATE
WHERE ANN_NO = #{annNo}
  AND BOARD_NO = #{boardNo}
  AND DEL_YN = 'N'

UPDATE APT_ANN_BOARD_POST
SET DEL_YN = 'Y'
  , MDF_DTTM = SYSDATE
WHERE ANN_NO = #{annNo}
  AND BOARD_NO = #{boardNo}
  AND DEL_YN = 'N'

mapper.select:
/* ImngrRegidentNoticeMapper.selectAptCmplexNoByMgmtOfcNo */
SELECT apt_cmplex_no
FROM mgmt_office
WHERE mgmt_ofc_no = #{mgmtOfcNo}
  AND use_yn = 'Y'

/* ImngrRegidentNoticeMapper.selectNoticeBoardNoByAptCmplexNo */
SELECT board_no
FROM apt_board_instance
WHERE apt_cmplex_no = #{aptCmplexNo}
  AND board_ty_cd = 'NOTICE'
  AND use_yn = 'Y'
